import { AnimatedIconFrame, type AnimatedIconProps } from "../icon-frame";
import "./mail.css";

export function AnimatedMailIcon(props: AnimatedIconProps) {
  return (
    <AnimatedIconFrame name="mail" {...props}>
      <rect data-part="body" x="2.5" y="4.5" width="19" height="15" rx="3" />
      <path data-part="flap" d="m3 7 7.47 5.13a2.7 2.7 0 0 0 3.06 0L21 7" />
    </AnimatedIconFrame>
  );
}

:is([data-icon-hover] .animated-icon, .animated-icon[data-icon-hover], .animated-icon[data-play]) {
  &[data-icon="mail"] {
    & [data-part="body"] {
      --icon-pulse: scale(1.03, 0.96);
      transform-origin: 12px 19.5px;
      animation-name: icon-pulse;
    }

    & [data-part="flap"] {
      transform-origin: 12px 7px;
      animation-name: icon-mail-flap;
      animation-duration: var(--icon-duration-long);
    }
  }
}

@keyframes icon-mail-flap {
  40%,
  62% {
    transform: scaleY(-0.85);
  }
  88% {
    transform: scaleY(1.08);
  }
}
